(() => {
'use strict';
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const esc = value => String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const normalize = value => String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const paragraphs = value => String(value??'').split(/\n\s*\n/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('');
const months = ['Sin mes asignado','Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const memoryNames = {testimonio:'Testimonio',fotografia:'Fotografía',audio:'Audio',video:'Video',documento:'Documento'};
let state=structuredClone(BC_SEED),connected=false,user=null,csrf='',map,clusters,markers=new Map(),chapterIndex=0,calendarMonth=new Date().getMonth()+1,memoryType='all';
let adminPage='records',adminFilter='',contentDraft=null,adminSubmissions=[],adminUsers=[],adminAssets=[],adminRevisions=[],selectedFiles=[],fileObjectURLs=[],contentDirty=false;
const filters={type:'baile',region:'Valparaíso',province:'',commune:'',month:'',query:''};
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4600);}
function art(source,decorative=false){
 if(!source)return '';
 const original=BC_ASSETS[source];
 if(original){const view=source==='andacollo'?'560 94 520 1362':'403 86 724 1424';const label=source==='andacollo'?'Ilustración de un músico danzante de Andacollo':'Ilustración de un músico danzante del norte';return `<svg viewBox="${view}" ${decorative?'aria-hidden="true"':`role="img" aria-label="${label}"`} xmlns="http://www.w3.org/2000/svg"><image href="${original}" width="1575" height="1575"/></svg>`;}
 return `<img src="${esc(source)}" alt="${decorative?'':'Imagen del sitio'}" loading="lazy">`;
}
function safeHref(value){try{const u=new URL(value,location.href);return ['https:','http:'].includes(u.protocol)?value:'#';}catch{return '#';}}
function options(items,value,emptyLabel){return `${emptyLabel!==undefined?`<option value="">${esc(emptyLabel)}</option>`:''}${items.map(i=>{const v=typeof i==='string'?i:i.value;const label=typeof i==='string'?i:i.label;return `<option value="${esc(v)}"${String(value)===String(v)?' selected':''}>${esc(label)}</option>`}).join('')}`;}
function badge(r){return `<span class="number-badge ${r.type}" style="--marker:${esc(r.color)}" aria-label="Ficha ${r.markerNumber}">${r.markerNumber}</span>`;}
function sorted(records){return [...records].sort((a,b)=>a.commune.localeCompare(b.commune,'es')||a.name.localeCompare(b.name,'es'));}
function filteredRecords(){return sorted(state.records.filter(r=>(filters.type==='all'||r.type===filters.type)&&(!filters.region||r.region===filters.region)&&(!filters.province||r.province===filters.province)&&(!filters.commune||r.communeCode===filters.commune)&&(!filters.month||(r.type==='fiesta'&&r.month===Number(filters.month)))&&(!filters.query||normalize([r.name,r.locality,r.commune,r.province,r.region].join(' ')).includes(normalize(filters.query)))));}
function apiURL(path){return new URL(path.replace(/^\//,''),new URL('./',location.href));}
async function request(path,{method='GET',body,headers={},timeout=20000}={}){
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeout);
 try{const response=await fetch(apiURL(path),{method,credentials:'same-origin',headers:{...(body?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':csrf}:{}),...headers},body:body?JSON.stringify(body):undefined,signal:controller.signal});let value;try{value=await response.json();}catch{throw new Error('La respuesta del sitio no pudo leerse.');}if(!response.ok)throw new Error(value.error||'No se pudo completar la operación.');return value;}finally{clearTimeout(timer);}
}
async function refresh(){state=await request('/api/state');connected=true;renderSite();renderRecords(false);renderCalendar();renderMemories();}
function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function showDialog(id){const d=$('#'+id);if(!d.open)d.showModal();}
function closeDialog(id){if(id==='admin-dialog'&&contentDirty&&!confirm('Hay cambios de contenido sin guardar. ¿Quieres cerrar sin guardarlos?'))return;$('#'+id).close();}

function renderSite(){
 const {intro,appearance:a,sections,extraSections=[]}=state.contents;
 for(const key of ['paper','ink','accent','navy'])document.documentElement.style.setProperty('--'+key,a[key]);
 document.title=a.pageTitle;document.querySelector('meta[name="description"]').content=a.description;
 $('#brand-name').textContent=a.brandName;$('#brand-subtitle').textContent=a.brandSubtitle;$('#footer-brand').textContent=a.brandName;$('#footer-subtitle').textContent=a.brandSubtitle;
 $('#brand-art').innerHTML=art(a.logoArt,true);$('#footer-art').innerHTML=art(a.logoArt,true);
 $('#hero-left').innerHTML=art(a.heroLeftArt);$('#hero-right').innerHTML=art(a.heroRightArt);
 $('#hero-eyebrow').textContent=intro.eyebrow;
 const title=String(intro.title||'');const comma=title.indexOf(',');$('#hero-title').innerHTML=comma>=0?`${esc(title.slice(0,comma+1))}<br><em>${esc(title.slice(comma+1).trim())}</em>`:esc(title);
 $('#hero-description').textContent=intro.description;$('#footer-text').textContent=a.footerText;
 $('#main-nav').innerHTML=sections.filter(s=>s.visible&&s.id!=='participa').map(s=>`<a href="#${esc(s.id)}">${esc(s.navLabel)}</a>`).join('')+extraSections.filter(s=>s.visible&&s.navLabel).map(s=>`<a href="#${esc(s.id)}">${esc(s.navLabel)}</a>`).join('');
 $('#social-links').innerHTML=[a.contactEmail?`<a href="mailto:${esc(a.contactEmail)}">Contacto</a>`:'',...['instagram','facebook'].filter(k=>a[k]).map(k=>`<a href="${esc(safeHref(a[k]))}" target="_blank" rel="noreferrer">${k==='instagram'?'Instagram':'Facebook'} ↗</a>`)].join('');
 const container=$('#sections');
 for(const s of sections){const el=$('#'+s.id);if(!el)continue;el.hidden=!s.visible;container.append(el);$(`[data-section-kicker="${s.id}"]`).textContent=s.kicker;$(`[data-section-title="${s.id}"]`).textContent=s.title;$(`[data-section-description="${s.id}"]`).textContent=s.description;}
 $$('.extra-section').forEach(n=>n.remove());
 for(const s of extraSections){if(!s.visible)continue;const el=document.createElement('section');el.id=s.id;el.className='extra-section page-width';el.innerHTML=`<p class="eyebrow">${esc(s.kicker)}</p><div class="${s.image?'extra-layout':''}"><div><h2>${esc(s.title)}</h2>${paragraphs(s.body)}</div>${s.image?`<img src="${esc(s.image)}" alt="${esc(s.imageAlt||s.title)}" loading="lazy">`:''}</div>`;container.insertBefore(el,$('#participa'));}
 for(const s of sections)$$(`a[href="#${s.id}"]`).forEach(a=>a.hidden=!s.visible);
 const bailes=state.records.filter(r=>r.type==='baile').length,fiestas=state.records.length-bailes,communes=new Set(state.records.map(r=>r.communeCode)).size;
 $('#stats').innerHTML=`<div class="stat"><strong>${bailes}</strong><span>Bailes en el registro</span></div><div class="stat"><strong>${fiestas}</strong><span>Fiestas y celebraciones</span></div><div class="stat"><strong>${communes}</strong><span>Comunas del recorrido</span></div><span class="stats-label">ARCHIVO TERRITORIAL · CHILE</span>`;
 renderStory();renderFilterOptions();
 $('#contribution-record').innerHTML=options(sorted(state.records).map(r=>({value:r.id,label:`${r.name} · ${r.commune}`})),'','Sin asociación específica');
 const territoryValue=$('#calendar-territory').value;$('#calendar-territory').innerHTML=options([...new Set(state.records.map(r=>r.commune))].sort((a,b)=>a.localeCompare(b,'es')),territoryValue,'Todas las comunas');
 $('#contribution-submit').innerHTML=connected?'Enviar aporte <span aria-hidden="true">↗</span>':'Descargar mi aporte <span aria-hidden="true">↓</span>';
 $('#contribution-mode').textContent=connected?'Tu aporte será revisado antes de aparecer en el archivo público.':'Prepara tu recuerdo y sus archivos para entregarlos al equipo del archivo. La descarga reúne todo en un solo archivo.';
 if(map)setTimeout(()=>map.invalidateSize(),80);
}
function renderStory(){const chapters=state.contents.chapters;chapterIndex=Math.min(chapterIndex,chapters.length-1);$('#story-tabs').innerHTML=chapters.map((c,i)=>`<button role="tab" id="chapter-${i}" aria-controls="story-panel" aria-selected="${i===chapterIndex}" data-chapter="${i}" class="${i===chapterIndex?'active':''}"><small>${String(i+1).padStart(2,'0')}</small>${esc(c.label)}</button>`).join('');const c=chapters[chapterIndex];$('#story-panel').setAttribute('aria-labelledby','chapter-'+chapterIndex);$('#story-panel').innerHTML=`<h3>${esc(c.title)}</h3>${paragraphs(c.body)}${c.source?`<a class="source-link" href="${esc(safeHref(c.source))}" target="_blank" rel="noreferrer">${esc(c.sourceLabel||'Consultar fuente')} ↗</a>`:''}`;}
function renderFilterOptions(){
 const territories=state.territories;
 $('#filter-region').innerHTML=options([...new Set(territories.map(t=>t.region))].sort(),filters.region,'Todo Chile');
 $('#filter-province').innerHTML=options([...new Set(territories.filter(t=>!filters.region||t.region===filters.region).map(t=>t.province))].sort(),filters.province,'Todas');
 $('#filter-commune').innerHTML=options(territories.filter(t=>(!filters.region||t.region===filters.region)&&(!filters.province||t.province===filters.province)).sort((a,b)=>a.name.localeCompare(b.name,'es')).map(t=>({value:t.code,label:t.name})),filters.commune,'Todas');
 $('#filter-month').innerHTML=options(months.slice(1).map((m,i)=>({value:i+1,label:m})),filters.month,'Todos los meses');
 $('#map-search').value=filters.query;
 $$('#type-filter button').forEach(b=>{b.classList.toggle('active',b.dataset.type===filters.type);b.setAttribute('aria-pressed',b.dataset.type===filters.type);});
}
function recordCard(r){return `<button class="record-card" data-open-record="${esc(r.id)}">${badge(r)}<span><span class="card-type">${r.type==='baile'?'Baile chino':'Fiesta'}</span><h3>${esc(r.name)}</h3><p>${esc(r.commune)}${r.locality?' · '+esc(r.locality):''}</p></span><span class="record-arrow" aria-hidden="true">↗</span></button>`;}
function renderRecords(fit=true){const records=filteredRecords();$('#map-results').innerHTML=records.length?records.map(recordCard).join(''):'<div class="empty-state">No hay coincidencias. Prueba otro nombre o territorio.</div>';$('#results-count').innerHTML=`<strong>${records.length}</strong> ${records.length===1?'registro':'registros'}`;$('#map-location').textContent=filters.commune?state.territories.find(t=>t.code===filters.commune)?.name:filters.province||filters.region||'Chile';if(map){clusters.clearLayers();markers.clear();for(const r of records){const marker=L.marker([r.lat,r.lng],{title:`${r.markerNumber}. ${r.name}`,alt:r.name,icon:L.divIcon({className:`bc-marker ${r.type}`,html:`<span style="--marker:${esc(r.color)}">${r.markerNumber}</span>`,iconSize:[28,28],iconAnchor:[14,14]})});marker.bindTooltip(`${r.markerNumber} · ${esc(r.name)}`,{direction:'top',offset:[0,-14]});marker.on('click',()=>openRecord(r.id));clusters.addLayer(marker);markers.set(r.id,marker);}if(fit&&records.length)fitRecords(records);}}
function fitRecords(records=filteredRecords()){if(!records.length)return;map.fitBounds(records.map(r=>[r.lat,r.lng]),{padding:[35,35],maxZoom:11,animate:false});}
function initMap(){if(!window.L){$('#map').innerHTML='<p class="empty-state">El mapa necesita que el navegador permita ejecutar JavaScript.</p>';return;}map=L.map('map',{scrollWheelZoom:false,maxZoom:18,minZoom:3}).setView([-32.8,-71],8);let baseLayer;const raster=()=>{if(baseLayer)map.removeLayer(baseLayer);baseLayer=L.tileLayer('https://tile.opentopomap.org/{z}/{x}/{y}.png',{maxZoom:17,attribution:'Datos © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>, SRTM · Estilo © <a href="https://opentopomap.org">OpenTopoMap</a> (CC-BY-SA)'}).addTo(map);};
 try{const canvas=document.createElement('canvas');const gl=canvas.getContext('webgl2')||canvas.getContext('webgl');if(!gl||!L.maplibreGL)raster();else{baseLayer=L.maplibreGL({style:'https://tiles.openfreemap.org/styles/liberty',attribution:'© <a href="https://openfreemap.org">OpenFreeMap</a> · © <a href="https://www.openmaptiles.org">OpenMapTiles</a> · © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(map);const glMap=baseLayer.getMaplibreMap?.();let failed=false;glMap?.on('error',()=>{if(!failed){failed=true;raster();}});}}catch{raster();}
 clusters=L.markerClusterGroup({showCoverageOnHover:false,zoomToBoundsOnClick:false,spiderfyOnMaxZoom:true,maxClusterRadius:35,iconCreateFunction:cluster=>L.divIcon({className:'bc-cluster',html:`<span>${cluster.getChildCount()}</span>`,iconSize:[37,37]})});
 clusters.on('clusterclick',event=>{const bounds=event.layer.getBounds();if(bounds.getNorthEast().distanceTo(bounds.getSouthWest())<10)event.layer.spiderfy();else event.layer.zoomToBounds({padding:[30,30]});});map.addLayer(clusters);renderRecords();
 for(const layer of state.layers||[]){if(!layer.geojson)continue;try{const item=L.geoJSON(layer.geojson,{style:{color:layer.color||'#586a48',weight:2},onEachFeature:(feature,l)=>{if(feature.properties?.name){const span=document.createElement('span');span.textContent=feature.properties.name;l.bindPopup(span);}}});const label=document.createElement('label');const input=document.createElement('input');input.type='checkbox';input.addEventListener('change',()=>input.checked?item.addTo(map):map.removeLayer(item));label.append(input,document.createTextNode(layer.name));$('#layer-controls').append(label);}catch{}}
}
function openRecord(id){const r=state.records.find(x=>x.id===id);if(!r)return;const related=sorted(state.records.filter(x=>x.communeCode===r.communeCode&&x.id!==r.id));const associated=r.type==='baile'?state.records.filter(f=>f.type==='fiesta'&&(f.participantIds||[]).includes(r.id)):state.records.filter(b=>(r.participantIds||[]).includes(b.id));
 const facts=[['Comuna',r.commune],['Provincia',r.province],['Región',r.region],...(r.locality?[['Localidad',r.locality]]:[]),...(r.type==='fiesta'&&r.month?[['Mes',months[r.month]]]:[]),...(r.date?[['Fecha',new Date(r.date+'T12:00:00').toLocaleDateString('es-CL')]]:[]),['Ubicación',r.precision==='exacta'?'Coordenadas del lugar':r.precision==='localidad'?'Referencia de localidad':'Referencia comunal']];
 $('#record-detail').innerHTML=`${r.photoUrl?`<img class="detail-photo" src="${esc(r.photoUrl)}" alt="${esc(r.name)}">`:''}<header class="detail-head"><div class="record-ident">${badge(r)}<span>${r.type==='baile'?'Baile chino':'Fiesta'} · Ficha ${r.markerNumber}</span></div><h2>${esc(r.name)}</h2><p>${esc(r.commune)} · ${esc(r.region)}</p></header><div class="detail-body"><dl class="detail-facts">${facts.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>${paragraphs(r.history||r.description)}${r.videoUrl?`<a class="text-link" target="_blank" rel="noreferrer" href="${esc(safeHref(r.videoUrl))}">Ver video ↗</a>`:''}${associated.length?`<h3 class="detail-section-title">${r.type==='baile'?'Festividades asociadas':'Agrupaciones participantes'}</h3><div class="related-list">${associated.map(x=>`<button data-open-record="${esc(x.id)}">${badge(x)}${esc(x.name)} ↗</button>`).join('')}</div>`:''}${related.length?`<h3 class="detail-section-title">Del mismo territorio</h3><div class="related-list">${related.slice(0,8).map(x=>`<button data-open-record="${esc(x.id)}">${badge(x)}<span>${esc(x.name)}<small class="card-type">${x.type==='baile'?'Baile chino':'Fiesta'}</small></span> ↗</button>`).join('')}</div>`:''}${r.source?`<p class="source-link">Fuente: ${esc(r.source)}</p>`:''}</div><footer class="detail-actions"><button class="button" data-locate="${esc(r.id)}">Ubicar en el mapa ↗</button><button class="button secondary" data-contribute-record="${esc(r.id)}">Compartir una memoria</button>${user?`<button class="button secondary" data-edit-record="${esc(r.id)}">Editar ficha</button>`:''}</footer>`;showDialog('record-dialog');}
function locateRecord(id){const r=state.records.find(x=>x.id===id);if(!r)return;Object.assign(filters,{type:r.type,region:r.region,province:r.province,commune:r.communeCode,query:'',month:''});renderFilterOptions();renderRecords(false);closeDialog('record-dialog');$('#mapa').scrollIntoView({behavior:'smooth'});setTimeout(()=>{map.invalidateSize();map.setView([r.lat,r.lng],13,{animate:false});const marker=markers.get(id);if(marker)clusters.zoomToShowLayer(marker,()=>marker.openTooltip());},250);}
function renderCalendar(){const commune=$('#calendar-territory').value;const fiestas=state.records.filter(r=>r.type==='fiesta'&&(!commune||r.commune===commune));$('#calendar-months').innerHTML=months.slice(1).map((m,i)=>`<button data-month="${i+1}" class="${calendarMonth===i+1?'active':''}" aria-pressed="${calendarMonth===i+1}"><span>${m}</span><strong>${fiestas.filter(f=>f.month===i+1).length}</strong></button>`).join('');const visible=sorted(fiestas.filter(f=>f.month===calendarMonth));$('#calendar-title').textContent=months[calendarMonth];$('#calendar-results').innerHTML=visible.length?visible.map(r=>`<article class="festival-card"><span class="card-type">${badge(r)}${r.date?esc(new Date(r.date+'T12:00:00').toLocaleDateString('es-CL')):esc(months[r.month])}</span><h4>${esc(r.name)}</h4><p>${esc(r.commune)}${r.locality?' · '+esc(r.locality):''}</p><div class="card-actions"><button data-open-record="${esc(r.id)}">Abrir ficha ↗</button><button data-locate="${esc(r.id)}">Ver en el mapa</button></div></article>`).join(''):'<div class="empty-state">No hay celebraciones registradas para este mes y territorio.</div>';}
function mediaMarkup(files=[]){return files.map(f=>{const url='media/'+f.id;return `<div class="file-media">${f.mime.startsWith('image/')?`<img src="${url}" alt="${esc(f.name)}" loading="lazy">`:f.mime.startsWith('audio/')?`<audio controls preload="none" src="${url}"></audio>`:`<a class="text-link" href="${url}" target="_blank" rel="noreferrer">Descargar ${esc(f.name)} ↓</a>`}<small>${esc(f.name)}</small></div>`;}).join('');}
function renderMemories(){const items=state.contributions.filter(c=>memoryType==='all'||c.kind===memoryType);$('#memory-grid').innerHTML=items.length?items.map(c=>{const photo=c.files?.find(f=>f.mime.startsWith('image/'));return `<button class="memory-card" data-open-memory="${esc(c.id)}">${photo?`<img src="media/${esc(photo.id)}" alt="${esc(c.title)}" loading="lazy">`:''}<div><span class="card-type">${esc(memoryNames[c.kind])} ${c.year?' · '+esc(c.year):''}</span><h3>${esc(c.title)}</h3><p>${esc(c.body.slice(0,145))}${c.body.length>145?'…':''}</p><small>${esc(c.name)}${c.territory?' · '+esc(c.territory):''} ↗</small></div></button>`;}).join(''):`<div class="empty-memory"><span class="empty-symbol" aria-hidden="true">“</span><div><h3>El próximo recuerdo puede ser el tuyo.</h3><p>Comparte una historia, identifica una imagen o ayúdanos a conservar un sonido.</p></div><a href="#participa" class="text-link">Dejar un aporte ↗</a></div>`;}
function openMemory(id){const c=state.contributions.find(x=>x.id===id);if(!c)return;$('#memory-detail').innerHTML=`<header class="detail-head"><p class="eyebrow">${esc(memoryNames[c.kind])}${c.year?' · '+esc(c.year):''}</p><h2>${esc(c.title)}</h2><p>${esc(c.name)}${c.territory?' · '+esc(c.territory):''}</p></header><div class="detail-body">${paragraphs(c.body)}${mediaMarkup(c.files)}${c.videoUrl?`<a href="${esc(safeHref(c.videoUrl))}" target="_blank" rel="noreferrer" class="text-link">Ver video ↗</a>`:''}${c.credit?`<p class="source-link">Crédito: ${esc(c.credit)}</p>`:''}${c.recordId?`<div class="detail-actions"><button class="button secondary" data-open-record="${esc(c.recordId)}">Ver baile o fiesta relacionado ↗</button></div>`:''}</div>`;showDialog('memory-dialog');}
function fileData(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,mime:file.type,data:String(reader.result).split(',')[1]});reader.onerror=()=>reject(new Error('No se pudo leer '+file.name));reader.readAsDataURL(file);});}
function updateFilePreviews(){fileObjectURLs.forEach(URL.revokeObjectURL);fileObjectURLs=[];$('#file-previews').innerHTML=selectedFiles.map(f=>{let url='';if(f.type.startsWith('image/')){url=URL.createObjectURL(f);fileObjectURLs.push(url);}return `<div class="file-preview">${url?`<img src="${url}" alt="Vista previa del archivo">`:''}<span>${esc(f.name)} · ${(f.size/1024/1024).toFixed(1)} MB</span></div>`;}).join('');}
async function submitContribution(event){event.preventDefault();const form=event.target,status=$('#contribution-status'),button=$('#contribution-submit');status.textContent='';if(!form.reportValidity())return;const value=Object.fromEntries(new FormData(form));value.consent=form.elements.consent.checked;delete value.website;value.website=form.elements.website.value;
 if(!value.body.trim()&&!value.videoUrl&&!selectedFiles.length){status.textContent='Escribe tu recuerdo o adjunta material.';return;}
 if(value.videoUrl&&!value.videoUrl.startsWith('https://')){status.textContent='El enlace de video debe comenzar con https://.';return;}
 button.disabled=true;try{value.files=await Promise.all(selectedFiles.map(fileData));if(connected){const answer=await request('/api/contributions',{method:'POST',body:value,timeout:90000});status.textContent='Aporte recibido. El equipo lo revisará antes de publicarlo. Referencia: '+answer.id.slice(0,8);form.reset();selectedFiles=[];updateFilePreviews();}else{downloadJSON({...value,preparedAt:new Date().toISOString()},'mi-aporte-bailes-chinos.json');status.textContent='Tu aporte está preparado. Entrega el archivo descargado al equipo del archivo.';}}catch(error){status.textContent=error.name==='AbortError'?'El envío tardó demasiado. Inténtalo nuevamente.':error.message;}finally{button.disabled=false;}}

// Administration is authenticated by the server. The standalone HTML never simulates a private session.
async function openAdmin(){showDialog('admin-dialog');if(!connected){$('#admin-body').innerHTML='<div class="admin-login"><h3>Administración del sitio</h3><p>Abre la instalación del sitio para iniciar sesión y editar los contenidos compartidos.</p><p>La vista descargable permite recorrer las páginas, el mapa y las fichas.</p><button class="button secondary" data-close="admin-dialog">Volver al sitio</button></div>';return;}try{const session=await request('/api/auth/session');user=session.user;csrf=session.csrf;if(user){contentDraft=structuredClone(state.contents);renderAdmin();}else renderLogin();}catch(error){$('#admin-body').innerHTML=`<div class="admin-login"><p>${esc(error.message)}</p><button class="button secondary" data-close="admin-dialog">Cerrar</button></div>`;}}
function renderLogin(message=''){$('#admin-body').innerHTML=`<form class="admin-login" id="admin-login"><h3>Ingresa a tu archivo</h3><p>Administra contenidos, agrupaciones y aportes de la comunidad.</p><label>Correo<input name="email" type="email" required autocomplete="username"></label><label>Contraseña<input name="password" type="password" required autocomplete="current-password"></label><p class="form-status" role="alert">${esc(message)}</p><button class="button" type="submit">Iniciar sesión →</button></form>`;}
function renderAdmin(){const nav=[['records','Bailes y fiestas'],['contents','Textos y secciones'],['images','Logo e imágenes'],['territories','Territorios'],['contributions','Aportes'],['revisions','Recuperar versiones'],...(user.role==='admin'?[['users','Usuarios']]:[])];$('#admin-body').innerHTML=`<div class="admin-layout"><nav class="admin-nav" aria-label="Administración">${nav.map(([id,label])=>`<button data-admin-page="${id}" class="${adminPage===id?'active':''}">${label}</button>`).join('')}<div class="admin-user">${esc(user.name)}<br>${esc(user.email)}</div><button class="logout" id="admin-logout">Cerrar sesión</button></nav><section class="admin-content" id="admin-content"></section></div>`;renderAdminPage();}
function field(label,name,value='',{type='text',full=false,required=false,textarea=false,optionsHTML='',attributes=''}={}){return `<label class="${full?'full':''}">${esc(label)}${textarea?`<textarea name="${name}" rows="5" ${attributes}>${esc(value)}</textarea>`:optionsHTML?`<select name="${name}" ${attributes}>${optionsHTML}</select>`:`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${attributes}>`}</label>`;}
function contentField(label,path,value,opts={}){return field(label,path,value,{...opts,attributes:`data-content-path="${esc(path)}" ${opts.attributes||''}`});}
function setPath(obj,path,value){const parts=path.split('.');let cursor=obj;for(const k of parts.slice(0,-1))cursor=cursor[k];cursor[parts.at(-1)]=value;}
function renderAdminPage(){if(adminPage==='records')renderAdminRecords();else if(adminPage==='contents')renderContentEditor();else if(adminPage==='images')renderImagesEditor();else if(adminPage==='territories')renderTerritories();else if(adminPage==='contributions')loadModeration();else if(adminPage==='revisions')loadRevisions();else if(adminPage==='users')loadUsers();}
function renderAdminRecords(){const records=sorted(state.records.filter(r=>!adminFilter||normalize([r.name,r.commune,r.province].join(' ')).includes(normalize(adminFilter))));$('#admin-content').innerHTML=`<h3>Bailes y fiestas</h3><p class="intro-text">Edita las fichas, sus colores, ubicaciones y relaciones. Los cambios se reflejan en el mapa y en el calendario.</p><div class="admin-toolbar"><input type="search" id="admin-search" value="${esc(adminFilter)}" placeholder="Buscar ficha o lugar" aria-label="Buscar fichas"><div><button class="button secondary" data-new-record="baile">+ Baile</button> <button class="button" data-new-record="fiesta">+ Fiesta</button></div></div><div class="table-scroll"><table><thead><tr><th>Ficha</th><th>Nombre</th><th>Territorio</th><th>Acciones</th></tr></thead><tbody>${records.map(r=>`<tr><td>${badge(r)}</td><td class="table-name">${esc(r.name)}<small>${r.type==='baile'?'Baile chino':months[r.month]||'Fiesta'}</small></td><td>${esc(r.commune)}<small>${esc(r.province)}</small></td><td><button data-edit-record="${esc(r.id)}">Editar</button><button data-open-record="${esc(r.id)}">Ver</button><button data-delete-record="${esc(r.id)}">Retirar</button></td></tr>`).join('')}</tbody></table></div>`;}
function renderContentEditor(){if(!contentDraft)contentDraft=structuredClone(state.contents);const d=contentDraft;$('#admin-content').innerHTML=`<h3>Textos y secciones</h3><p class="intro-text">Cambia los textos, los títulos del menú, el orden y la visibilidad de las secciones. Puedes agregar capítulos y páginas de contenido.</p><div class="admin-group"><h4>Portada y presentación</h4><div class="form-grid">${contentField('Nombre de la marca','appearance.brandName',d.appearance.brandName)}${contentField('Bajada de la marca','appearance.brandSubtitle',d.appearance.brandSubtitle)}${contentField('Título de la portada','intro.title',d.intro.title,{full:true})}${contentField('Texto de la portada','intro.description',d.intro.description,{full:true,textarea:true})}${contentField('Frase superior de portada','intro.eyebrow',d.intro.eyebrow,{full:true})}${contentField('Título de la pestaña del navegador','appearance.pageTitle',d.appearance.pageTitle,{full:true})}${contentField('Descripción para buscadores','appearance.description',d.appearance.description,{full:true,textarea:true})}</div></div><div class="admin-group"><h4>Menú y orden de las secciones</h4>${d.sections.map((s,i)=>`<div class="section-row"><div><input type="checkbox" data-content-path="sections.${i}.visible" ${s.visible?'checked':''} aria-label="Mostrar ${esc(s.navLabel)}"><span class="section-name">${esc(s.navLabel)}</span></div><div class="section-controls"><button data-move-section="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="Subir ${esc(s.navLabel)}">↑ Subir</button><button data-move-section="${i}" data-direction="1" ${i===d.sections.length-1?'disabled':''} aria-label="Bajar ${esc(s.navLabel)}">↓ Bajar</button></div></div><details class="chapter-edit"><summary>Editar textos de ${esc(s.navLabel)}</summary><div class="form-grid">${contentField('Nombre en el menú',`sections.${i}.navLabel`,s.navLabel)}${contentField('Frase superior',`sections.${i}.kicker`,s.kicker)}${contentField('Título',`sections.${i}.title`,s.title,{full:true})}${contentField('Descripción',`sections.${i}.description`,s.description,{full:true,textarea:true})}</div></details>`).join('')}</div><div class="admin-group"><h4>Historia y contenidos patrimoniales</h4>${d.chapters.map((c,i)=>`<details class="chapter-edit"><summary><span>${String(i+1).padStart(2,'0')} · ${esc(c.label)}</span></summary><div><div class="form-grid">${contentField('Nombre de la pestaña',`chapters.${i}.label`,c.label)}${contentField('Título',`chapters.${i}.title`,c.title)}${contentField('Texto',`chapters.${i}.body`,c.body,{full:true,textarea:true})}${contentField('Nombre de la fuente',`chapters.${i}.sourceLabel`,c.sourceLabel)}${contentField('Enlace de la fuente',`chapters.${i}.source`,c.source,{type:'url'})}</div><div class="chapter-actions"><button data-move-chapter="${i}" data-direction="-1" ${i===0?'disabled':''}>↑ Subir</button><button data-move-chapter="${i}" data-direction="1" ${i===d.chapters.length-1?'disabled':''}>↓ Bajar</button><button data-delete-chapter="${i}">Retirar capítulo</button></div></div></details>`).join('')}<button class="button secondary" id="add-chapter">+ Agregar capítulo</button></div><div class="admin-group"><h4>Secciones adicionales</h4>${d.extraSections.map((s,i)=>`<details class="chapter-edit"><summary>${esc(s.title||'Nueva sección')}</summary><div class="form-grid">${contentField('Título',`extraSections.${i}.title`,s.title,{full:true})}${contentField('Nombre en el menú',`extraSections.${i}.navLabel`,s.navLabel)}${contentField('Frase superior',`extraSections.${i}.kicker`,s.kicker)}${contentField('Texto',`extraSections.${i}.body`,s.body,{full:true,textarea:true})}${contentField('Imagen',`extraSections.${i}.image`,s.image||'',{full:true})}<label class="full">Cargar imagen<input type="file" accept="image/png,image/jpeg,image/webp" data-extra-upload="${i}"></label>${contentField('Descripción de la imagen',`extraSections.${i}.imageAlt`,s.imageAlt||'',{full:true})}<label class="consent full"><input type="checkbox" data-content-path="extraSections.${i}.visible" ${s.visible?'checked':''}>Mostrar sección</label></div><div class="chapter-actions"><button data-delete-extra="${i}">Retirar sección</button></div></details>`).join('')}<button class="button secondary" id="add-extra">+ Agregar sección</button></div><div class="admin-group"><h4>Pie de página y contacto</h4><div class="form-grid">${contentField('Texto del pie de página','appearance.footerText',d.appearance.footerText,{full:true})}${contentField('Correo de contacto','appearance.contactEmail',d.appearance.contactEmail,{type:'email'})}${contentField('Instagram','appearance.instagram',d.appearance.instagram,{type:'url'})}${contentField('Facebook','appearance.facebook',d.appearance.facebook,{type:'url'})}</div></div>${saveBar()}`;}
function saveBar(){return '<div class="admin-savebar"><span>Se conserva una versión anterior para poder recuperarla.</span><button class="button" id="save-content">Guardar cambios</button></div>';}
function renderImagesEditor(){if(!contentDraft)contentDraft=structuredClone(state.contents);const a=contentDraft.appearance;$('#admin-content').innerHTML=`<h3>Logo, imágenes y colores</h3><p class="intro-text">Reemplaza una imagen o vuelve a las ilustraciones originales. Guarda los cambios cuando estés conforme.</p><div class="art-editor-grid">${[['logoArt','Logo'],['heroLeftArt','Ilustración izquierda'],['heroRightArt','Ilustración derecha']].map(([key,label])=>`<div class="art-editor"><h4>${label}</h4><div class="art-preview" id="preview-${key}">${art(a[key])}</div><label>Ilustración original<select data-art-select="${key}">${options([{value:'andacollo',label:'Bailarín de Andacollo'},{value:'norte',label:'Baile chino del norte'},{value:'',label:'Sin imagen'},...(a[key]&&!BC_ASSETS[a[key]]?[{value:a[key],label:'Imagen cargada'}]:[])],a[key])}</select></label><label>Cargar nueva imagen<input type="file" data-art-upload="${key}" accept="image/png,image/jpeg,image/webp"></label><button data-restore-art="${key}">Restaurar original</button></div>`).join('')}</div><div class="admin-group"><h4>Colores del sitio</h4><div class="form-grid">${[['paper','Fondo'],['ink','Texto'],['accent','Acento'],['navy','Botones y navegación']].map(([key,label])=>contentField(label,'appearance.'+key,a[key],{type:'color'})).join('')}</div></div><div class="admin-group"><h4>Imágenes que ya cargaste</h4><p class="intro-text">Puedes reutilizarlas sin volver a subir el archivo.</p><div id="asset-library" class="memory-grid"><p class="intro-text">Cargando imágenes…</p></div></div>${saveBar()}`;loadAssets();}
async function loadAssets(){try{adminAssets=await request('/api/admin/assets');if(!$('#asset-library'))return;$('#asset-library').innerHTML=adminAssets.length?adminAssets.slice(0,30).map(a=>`<div class="art-editor"><div class="art-preview"><img src="uploads/${a.id}" alt="${esc(a.name)}" loading="lazy"></div><small>${esc(a.name)}</small><button data-use-asset="${a.id}" data-slot="logoArt">Usar como logo</button><button data-use-asset="${a.id}" data-slot="heroLeftArt">Usar a la izquierda</button><button data-use-asset="${a.id}" data-slot="heroRightArt">Usar a la derecha</button></div>`).join(''):'<p class="intro-text">Aquí aparecerán las imágenes que cargues desde el panel.</p>';}catch(error){if($('#asset-library'))$('#asset-library').textContent=error.message;}}
async function uploadAsset(file){if(!file||file.size>8*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('Selecciona PNG, JPG o WebP de hasta 8 MB.');return request('/api/admin/assets',{method:'POST',body:await fileData(file),timeout:90000});}
async function saveContents(button){button.disabled=true;try{await request('/api/admin/contents',{method:'PUT',body:contentDraft,headers:{'If-Match':String(state.contentRevision||0)}});contentDirty=false;await refresh();contentDraft=structuredClone(state.contents);toast('Cambios guardados en el sitio.');renderAdminPage();}catch(error){toast(error.message);}finally{button.disabled=false;}}
function openEditor(id='',kind='baile'){const original=state.records.find(r=>r.id===id);const defaultT=state.territories.find(t=>t.code===filters.commune)||state.territories.find(t=>t.name==='Putaendo')||state.territories[0];const r=original||{type:kind,name:'',communeCode:defaultT.code,locality:'',lat:defaultT.lat,lng:defaultT.lng,precision:'comuna',month:0,date:'',history:'',source:'',photoUrl:'',videoUrl:'',color:'',participantIds:[],revision:0};const baileRelations=state.records.filter(f=>f.type==='fiesta'&&(f.participantIds||[]).includes(id)).map(f=>f.id);const possible=sorted(state.records.filter(x=>x.type!==(r.type)));$('#editor-body').innerHTML=`<form id="record-editor" data-record-id="${esc(id)}" data-type="${r.type}" data-revision="${r.revision}"><header class="editor-header"><h2>${id?'Editar':'Agregar'} ${r.type==='baile'?'baile':'fiesta'}</h2><button type="button" data-close="editor-dialog" aria-label="Cerrar editor">×</button></header><div class="editor-content"><div class="form-grid">${field('Nombre *','name',r.name,{full:true,required:true})}${field('Comuna *','communeCode',r.communeCode,{optionsHTML:options([...state.territories].sort((a,b)=>a.name.localeCompare(b.name,'es')).map(t=>({value:t.code,label:`${t.name} · ${t.region}`})),r.communeCode)})}${field('Localidad','locality',r.locality)}${field('Precisión de la ubicación','precision',r.precision,{optionsHTML:options([{value:'comuna',label:'Referencia comunal'},{value:'localidad',label:'Referencia de localidad'},{value:'exacta',label:'Coordenadas del lugar'}],r.precision)})}${field('Color de la ficha','color',r.color||'#ad4c34',{type:'color',attributes:!id?'data-auto-color="true"':''})}${field('Latitud','lat',r.lat,{type:'number',attributes:'step="any" min="-90" max="90" required'})}${field('Longitud','lng',r.lng,{type:'number',attributes:'step="any" min="-180" max="180" required'})}${r.type==='fiesta'?field('Mes','month',r.month,{optionsHTML:options(months.map((m,i)=>({value:i,label:m})),r.month)})+field('Fecha exacta, si está confirmada','date',r.date,{type:'date'}):''}${field('Historia y antecedentes','history',r.history||r.description,{full:true,textarea:true})}${field('Fuente de la información','source',r.source,{full:true})}${field('Imagen de la ficha','photoUrl',r.photoUrl,{full:true})}<label class="full">Cargar imagen<input type="file" id="record-photo-upload" accept="image/png,image/jpeg,image/webp"></label>${field('Enlace de video','videoUrl',r.videoUrl,{full:true,type:'url'})}<div class="full"><label for="participant-search">${r.type==='fiesta'?'Agrupaciones participantes':'Fiestas en que participa'}</label><small>Marca solo relaciones conocidas o confirmadas por la agrupación.</small><input type="search" id="participant-search" placeholder="Buscar una asociación"><div class="participants">${possible.map(x=>`<label data-participant-name="${esc(normalize(x.name+' '+x.commune))}"><input type="checkbox" name="relations" value="${esc(x.id)}" ${(r.type==='fiesta'?(r.participantIds||[]):baileRelations).includes(x.id)?'checked':''}><span>${esc(x.name)} · ${esc(x.commune)}</span></label>`).join('')}</div></div></div><p class="form-status" id="editor-status" role="alert"></p></div><footer class="editor-footer"><button type="button" data-close="editor-dialog">Cancelar</button><button class="button" type="submit">Guardar ficha</button></footer></form>`;showDialog('editor-dialog');}
async function saveRecord(event){event.preventDefault();const form=event.target;if(!form.reportValidity())return;const button=$('button[type=submit]',form),r=Object.fromEntries(new FormData(form));r.type=form.dataset.type;r.revision=Number(form.dataset.revision);r.lat=Number(r.lat);r.lng=Number(r.lng);r.month=Number(r.month||0);r[r.type==='fiesta'?'participantIds':'fiestaIds']=[...new FormData(form).getAll('relations')];delete r.relations;if(!form.dataset.recordId&&form.elements.color.dataset.autoColor==='true')delete r.color;button.disabled=true;try{await request('/api/admin/records'+(form.dataset.recordId?'/'+form.dataset.recordId:''),{method:form.dataset.recordId?'PUT':'POST',body:r});closeDialog('editor-dialog');await refresh();if($('#admin-dialog').open)renderAdminPage();toast('Ficha guardada.');}catch(error){$('#editor-status').textContent=error.message;}finally{button.disabled=false;}}
function renderTerritories(){const list=state.territories.filter(t=>!adminFilter||normalize(t.name+' '+t.province+' '+t.region).includes(normalize(adminFilter)));$('#admin-content').innerHTML=`<h3>Territorios</h3><p class="intro-text">Actualiza los datos comunales y su referencia geográfica. Las fichas con ubicación comunal se actualizarán junto con su territorio.</p><div class="admin-toolbar"><input id="territory-search" type="search" value="${esc(adminFilter)}" placeholder="Buscar comuna, provincia o región" aria-label="Buscar territorio"></div><div class="table-scroll"><table><thead><tr><th>Comuna</th><th>Provincia</th><th>Región</th><th>Acciones</th></tr></thead><tbody>${list.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.province)}</td><td>${esc(t.region)}</td><td><button data-edit-territory="${esc(t.code)}">Editar</button></td></tr>`).join('')}</tbody></table></div>`;}
function editTerritory(code){const t=state.territories.find(x=>x.code===code);if(!t)return;$('#editor-body').innerHTML=`<form id="territory-editor" data-code="${esc(code)}"><header class="editor-header"><h2>Editar territorio</h2><button type="button" data-close="editor-dialog">×</button></header><div class="editor-content"><div class="form-grid">${field('Comuna','name',t.name,{required:true})}${field('Provincia','province',t.province,{required:true})}${field('Región','region',t.region,{required:true,full:true})}${field('Latitud','lat',t.lat,{type:'number',attributes:'step="any" required'})}${field('Longitud','lng',t.lng,{type:'number',attributes:'step="any" required'})}${field('Antecedentes del territorio','description',t.description||'',{textarea:true,full:true})}</div><p id="editor-status" class="form-status" role="alert"></p></div><footer class="editor-footer"><button type="button" data-close="editor-dialog">Cancelar</button><button class="button" type="submit">Guardar territorio</button></footer></form>`;showDialog('editor-dialog');}
async function loadModeration(){const host=$('#admin-content');host.innerHTML='<h3>Aportes de la comunidad</h3><p class="intro-text">Cargando aportes…</p>';try{adminSubmissions=await request('/api/admin/contributions');if(adminPage!=='contributions')return;host.innerHTML=`<h3>Aportes de la comunidad</h3><p class="intro-text">Revisa los testimonios y sus archivos antes de publicarlos. El contacto del autor queda reservado al equipo.</p><div class="admin-toolbar"><button class="button secondary" id="import-contribution">Importar un aporte descargado</button><input id="import-contribution-file" type="file" accept="application/json,.json" hidden></div>${adminSubmissions.length?adminSubmissions.map(c=>`<article class="moderation-card"><span class="badge status-${c.status}">${{pending:'Por revisar',approved:'Publicado',rejected:'Reservado'}[c.status]}</span><h4>${esc(c.title)}</h4><p class="meta">${esc(c.name)} · ${esc(memoryNames[c.kind])}${c.territory?' · '+esc(c.territory):''}${c.year?' · '+esc(c.year):''}</p><p>${esc(c.body)}</p>${c.contact?`<p class="meta">Contacto: ${esc(c.contact)}</p>`:''}${c.credit?`<p class="meta">Crédito: ${esc(c.credit)}</p>`:''}${mediaMarkup(c.files)}${c.videoUrl?`<a class="source-link" href="${esc(safeHref(c.videoUrl))}" target="_blank" rel="noreferrer">Abrir video ↗</a>`:''}<div class="moderation-actions"><button class="approve" data-moderate="${c.id}" data-status="approved">Publicar</button><button data-moderate="${c.id}" data-status="rejected">Reservar sin publicar</button><button data-moderate="${c.id}" data-status="pending">Volver a revisión</button></div></article>`).join(''):'<div class="storage-info">Los nuevos aportes aparecerán aquí para tu revisión.</div>'}`;}catch(error){host.innerHTML=`<p>${esc(error.message)}</p>`;}}
async function loadUsers(){const host=$('#admin-content');host.innerHTML='<h3>Usuarios autorizados</h3>';try{adminUsers=await request('/api/admin/users');if(adminPage!=='users')return;host.innerHTML=`<h3>Usuarios autorizados</h3><p class="intro-text">Los editores gestionan contenidos y aportes. Los administradores también pueden habilitar cuentas.</p><form id="create-user" class="admin-group"><div class="form-grid">${field('Nombre','name','',{required:true})}${field('Correo','email','',{type:'email',required:true})}${field('Contraseña inicial','password','',{type:'password',required:true,attributes:'minlength="12" autocomplete="new-password"'})}${field('Rol','role','editor',{optionsHTML:options([{value:'editor',label:'Editor'},{value:'admin',label:'Administrador'}],'editor')})}</div><p class="form-status" id="user-status" role="alert"></p><button class="button" type="submit">Crear usuario</button></form><div class="table-scroll"><table><thead><tr><th>Nombre</th><th>Correo</th><th>Rol</th><th>Acceso</th></tr></thead><tbody>${adminUsers.map(u=>`<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${u.role==='admin'?'Administrador':'Editor'}</td><td>${u.id===user.id?'Tu cuenta':`<button data-toggle-user="${u.id}" data-active="${!u.active}">${u.active?'Desactivar':'Activar'}</button>`}</td></tr>`).join('')}</tbody></table></div>`;}catch(error){host.innerHTML=`<p>${esc(error.message)}</p>`;}}
async function loadRevisions(){const host=$('#admin-content');host.innerHTML='<h3>Recuperar versiones</h3>';try{adminRevisions=await request('/api/admin/revisions');if(adminPage!=='revisions')return;host.innerHTML=`<h3>Recuperar versiones</h3><p class="intro-text">Si cambiaste una imagen o un texto y prefieres volver atrás, recupera una versión anterior. La recuperación también conserva el estado actual.</p><div class="admin-toolbar"><button class="button secondary" id="export-records">Exportar datos del sitio</button></div>${adminRevisions.length?`<div class="table-scroll"><table><thead><tr><th>Contenido</th><th>Guardado</th><th>Acción</th></tr></thead><tbody>${adminRevisions.map(r=>`<tr><td>${esc(r.entity==='contents'?'Textos, imágenes y diseño del sitio':r.entity==='record'?(state.records.find(x=>x.id===r.entity_key)?.name||'Ficha retirada'):state.territories.find(x=>x.code===r.entity_key)?.name||'Territorio')}</td><td>${esc(new Date(r.created).toLocaleString('es-CL'))}</td><td><button data-restore-revision="${r.id}">Recuperar</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="storage-info">Al guardar cambios, las versiones anteriores aparecerán aquí.</div>'}`;}catch(error){host.innerHTML=`<p>${esc(error.message)}</p>`;}}

document.addEventListener('click',async event=>{
 const b=event.target.closest('button,a');if(!b)return;
 if(b.dataset.close){closeDialog(b.dataset.close);return;}
 if(b.dataset.openRecord){openRecord(b.dataset.openRecord);return;}
 if(b.dataset.locate){locateRecord(b.dataset.locate);return;}
 if(b.dataset.contributeRecord){closeDialog('record-dialog');$('#contribution-record').value=b.dataset.contributeRecord;$('#participa').scrollIntoView({behavior:'smooth'});return;}
 if(b.dataset.openMemory){openMemory(b.dataset.openMemory);return;}
 if(b.dataset.chapter!==undefined){chapterIndex=Number(b.dataset.chapter);renderStory();return;}
 if(b.dataset.month){calendarMonth=Number(b.dataset.month);renderCalendar();return;}
 if(b.dataset.type){filters.type=b.dataset.type;if(filters.type!=='fiesta')filters.month='';renderFilterOptions();renderRecords();return;}
 if(b.dataset.memory){memoryType=b.dataset.memory;$$('#memory-filters button').forEach(x=>x.classList.toggle('active',x===b));renderMemories();return;}
 if(b.id==='clear-filters'){Object.assign(filters,{region:'',province:'',commune:'',query:'',month:''});renderFilterOptions();renderRecords();return;}
 if(b.id==='national-view'){Object.assign(filters,{region:'',province:'',commune:''});renderFilterOptions();renderRecords(false);map.fitBounds([[-56,-77],[-17,-66]],{padding:[20,20],animate:false});return;}
 if(b.id==='results-view'){fitRecords();return;}
 if(b.id==='menu-toggle'){const open=$('#main-nav').classList.toggle('open');b.setAttribute('aria-expanded',open);return;}
 if(b.closest('#main-nav')){$('#main-nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}
 if(b.id==='admin-open'){openAdmin();return;}
 if(b.dataset.adminPage){if(contentDirty&&['contents','images'].includes(adminPage)&&!['contents','images'].includes(b.dataset.adminPage)&&!confirm('Hay cambios sin guardar. ¿Quieres continuar sin guardarlos?'))return;adminPage=b.dataset.adminPage;adminFilter='';renderAdmin();return;}
 if(b.id==='admin-logout'){try{await request('/api/auth/logout',{method:'POST'});user=null;csrf='';contentDraft=null;contentDirty=false;renderLogin();}catch(error){toast(error.message);}return;}
 if(b.dataset.newRecord){openEditor('',b.dataset.newRecord);return;}
 if(b.dataset.editRecord){if(!user)return;openEditor(b.dataset.editRecord);return;}
 if(b.dataset.deleteRecord){const r=state.records.find(x=>x.id===b.dataset.deleteRecord);if(!r||!confirm('¿Retirar «'+r.name+'» del mapa? Podrás recuperarlo desde las versiones.'))return;try{await request('/api/admin/records/'+r.id,{method:'DELETE'});await refresh();renderAdminPage();toast('Ficha retirada. Puedes recuperarla desde las versiones.');}catch(error){toast(error.message);}return;}
 if(b.id==='save-content'){saveContents(b);return;}
 for(const [attr,key,render] of [['moveSection','sections',renderContentEditor],['moveChapter','chapters',renderContentEditor]]){if(b.dataset[attr]!==undefined){const i=Number(b.dataset[attr]),j=i+Number(b.dataset.direction),list=contentDraft[key];if(j>=0&&j<list.length){[list[i],list[j]]=[list[j],list[i]];contentDirty=true;render();}return;}}
 if(b.id==='add-chapter'){contentDraft.chapters.push({id:'capitulo-'+Date.now(),label:'Nuevo capítulo',title:'Título del capítulo',body:'Escribe aquí el contenido.',source:'',sourceLabel:''});contentDirty=true;renderContentEditor();return;}
 if(b.dataset.deleteChapter!==undefined){if(contentDraft.chapters.length<2){toast('Mantén al menos un capítulo.');return;}if(confirm('¿Retirar este capítulo?')){contentDraft.chapters.splice(Number(b.dataset.deleteChapter),1);contentDirty=true;renderContentEditor();}return;}
 if(b.id==='add-extra'){contentDraft.extraSections.push({id:'seccion-'+Date.now(),navLabel:'Nueva sección',kicker:'',title:'Nueva sección',body:'Escribe aquí el contenido.',image:'',imageAlt:'',visible:true});contentDirty=true;renderContentEditor();return;}
 if(b.dataset.deleteExtra!==undefined){if(confirm('¿Retirar esta sección?')){contentDraft.extraSections.splice(Number(b.dataset.deleteExtra),1);contentDirty=true;renderContentEditor();}return;}
 if(b.dataset.restoreArt){const key=b.dataset.restoreArt;contentDraft.appearance[key]=key==='heroRightArt'?'norte':'andacollo';contentDirty=true;renderImagesEditor();return;}
 if(b.dataset.useAsset){contentDraft.appearance[b.dataset.slot]='/uploads/'+b.dataset.useAsset;contentDirty=true;renderImagesEditor();return;}
 if(b.dataset.editTerritory){editTerritory(b.dataset.editTerritory);return;}
 if(b.dataset.moderate){b.disabled=true;try{await request('/api/admin/contributions/'+b.dataset.moderate,{method:'PATCH',body:{status:b.dataset.status}});await refresh();await loadModeration();toast('Estado del aporte actualizado.');}catch(error){toast(error.message);}finally{b.disabled=false;}return;}
 if(b.id==='import-contribution'){$('#import-contribution-file').click();return;}
 if(b.dataset.toggleUser){try{await request('/api/admin/users/'+b.dataset.toggleUser,{method:'PATCH',body:{active:b.dataset.active==='true'}});loadUsers();toast('Acceso actualizado.');}catch(error){toast(error.message);}return;}
 if(b.dataset.restoreRevision){if(!confirm('¿Recuperar esta versión? El estado actual se conservará en el historial.'))return;try{await request('/api/admin/revisions/'+b.dataset.restoreRevision,{method:'POST',body:{}});await refresh();contentDraft=structuredClone(state.contents);await loadRevisions();toast('Versión recuperada.');}catch(error){toast(error.message);}return;}
 if(b.id==='export-records'){try{downloadJSON(await request('/api/admin/export'),'respaldo-datos-bailes-chinos.json');toast('Datos exportados.');}catch(error){toast(error.message);}}
});
document.addEventListener('input',event=>{
 const e=event.target;if(e.dataset.contentPath){setPath(contentDraft,e.dataset.contentPath,e.type==='checkbox'?e.checked:e.value);contentDirty=true;}
 if(e.id==='map-search'){filters.query=e.value;renderRecords(false);}
 if(e.id==='admin-search'){const pos=e.selectionStart;adminFilter=e.value;renderAdminRecords();const next=$('#admin-search');next.focus();next.setSelectionRange(pos,pos);}
 if(e.id==='territory-search'){const pos=e.selectionStart;adminFilter=e.value;renderTerritories();const next=$('#territory-search');next.focus();next.setSelectionRange(pos,pos);}
 if(e.id==='participant-search'){$$('[data-participant-name]').forEach(l=>l.hidden=!l.dataset.participantName.includes(normalize(e.value)));}
 if(e.name==='color'&&e.closest('#record-editor'))delete e.dataset.autoColor;
});
document.addEventListener('change',async event=>{
 const e=event.target;
 if(e.id.startsWith('filter-')){const key=e.id.slice(7);filters[key]=e.value;if(key==='region'){filters.province='';filters.commune='';}if(key==='province')filters.commune='';if(key==='month'&&e.value)filters.type='fiesta';renderFilterOptions();renderRecords();return;}
 if(e.id==='calendar-territory'){renderCalendar();return;}
 if(e.id==='contribution-files'){const files=[...e.files];if(files.length>3||files.some(f=>f.size>8*1024*1024)){e.value='';toast('Puedes adjuntar hasta tres archivos de 8 MB.');return;}selectedFiles=files;updateFilePreviews();return;}
 if(e.dataset.artSelect){contentDraft.appearance[e.dataset.artSelect]=e.value;contentDirty=true;$('#preview-'+e.dataset.artSelect).innerHTML=art(e.value);return;}
 if(e.dataset.artUpload){try{e.disabled=true;const asset=await uploadAsset(e.files[0]);contentDraft.appearance[e.dataset.artUpload]=asset.url;contentDirty=true;renderImagesEditor();toast('Imagen cargada. Guarda cambios para usarla.');}catch(error){toast(error.message);e.disabled=false;}return;}
 if(e.dataset.extraUpload!==undefined){try{const asset=await uploadAsset(e.files[0]);contentDraft.extraSections[Number(e.dataset.extraUpload)].image=asset.url;contentDirty=true;renderContentEditor();toast('Imagen cargada. Guarda los cambios.');}catch(error){toast(error.message);}return;}
 if(e.id==='record-photo-upload'){try{const asset=await uploadAsset(e.files[0]);$('#record-editor').elements.photoUrl.value=asset.url;toast('Imagen cargada. Guarda la ficha.');}catch(error){toast(error.message);}return;}
 if(e.closest('#record-editor')&&(e.name==='communeCode'||e.name==='precision')){const f=$('#record-editor'),t=state.territories.find(x=>x.code===f.elements.communeCode.value);if(t&&f.elements.precision.value==='comuna'){f.elements.lat.value=t.lat;f.elements.lng.value=t.lng;}return;}
 if(e.id==='import-contribution-file'){try{if(!e.files[0])return;if(e.files[0].size>35*1024*1024)throw new Error('El aporte supera el tamaño permitido.');const v=JSON.parse(await e.files[0].text());delete v.preparedAt;v.website='';await request('/api/admin/import-contribution',{method:'POST',body:v,timeout:90000});await loadModeration();toast('Aporte importado a la bandeja de revisión.');}catch(error){toast(error.message);}return;}
});
document.addEventListener('submit',async event=>{
 const f=event.target;
 if(f.id==='contribution-form'){submitContribution(event);return;}
 if(f.id==='record-editor'){saveRecord(event);return;}
 if(f.id==='admin-login'){event.preventDefault();const b=$('button[type=submit]',f);b.disabled=true;try{const answer=await request('/api/auth/login',{method:'POST',body:Object.fromEntries(new FormData(f))});user=answer.user;csrf=answer.csrf;contentDraft=structuredClone(state.contents);renderAdmin();toast('Sesión iniciada.');}catch(error){renderLogin(error.message);}return;}
 if(f.id==='territory-editor'){event.preventDefault();const b=$('button[type=submit]',f);b.disabled=true;try{const v=Object.fromEntries(new FormData(f));await request('/api/admin/territories/'+f.dataset.code,{method:'PUT',body:v});closeDialog('editor-dialog');await refresh();renderTerritories();toast('Territorio guardado.');}catch(error){$('#editor-status').textContent=error.message;}finally{b.disabled=false;}return;}
 if(f.id==='create-user'){event.preventDefault();const b=$('button[type=submit]',f);b.disabled=true;try{await request('/api/admin/users',{method:'POST',body:Object.fromEntries(new FormData(f))});loadUsers();toast('Usuario creado.');}catch(error){$('#user-status').textContent=error.message;}finally{b.disabled=false;}}
});
$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog(d.id);}}));
$('#admin-dialog').addEventListener('cancel',e=>{if(contentDirty){e.preventDefault();closeDialog('admin-dialog');}});
async function boot(){renderSite();renderCalendar();renderMemories();initMap();if(location.protocol!=='file:'){try{const fresh=await request('/api/state',{timeout:4500});if(Array.isArray(fresh.records)&&fresh.contents){state=fresh;connected=true;renderSite();renderRecords(false);renderCalendar();renderMemories();}}catch{}}if(new URLSearchParams(location.search).has('admin'))openAdmin();}
boot();
})();
